head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDMGT50200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_22_onclick
 * @description 「서식대분류관리」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_22_onclick = async function(e){
    try {
        await scwin.excel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50200.img_22_onclick' }); }
};

/**
 * @method
 * @name img_24_onclick
 * @description img_24 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_24_onclick = async function(e){
    try {
        await scwin.popInsert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50200.img_24_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Excel
 * @description Excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/formUpclass.do",
        ref: "dma_ExcelReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name tx_fn_Delete_xhr
 * @description Delete xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr", unresolved: "action:self_submit:tx_fn_Delete_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/formUpclass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "findFormUpclasses");
    await scwin.tx_fn_List_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    $c.util.getComponent('txt_listDiv').setValue(responseText);
};

/**
 * @method
 * @name popInsert
 * @description pop Insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popInsert = async function () {
    const _url = "/filing/formUpclass.do?method=prepareUpdateFormUpclass&mode=create";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "formUpclassPop", popupName: "formUpclassPop", width: "400", height: "250" }, {});
};

/**
 * @method
 * @name popModify
 * @description pop Modify 처리
 * @param {String} formUpclssCd formUpclssCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popModify = async function (formUpclssCd) {
    const _url = "/filing/formUpclass.do?method=prepareUpdateFormUpclass&formUpclssCd=" + formUpclssCd + "&mode=update";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "formUpclassPop", popupName: "formUpclassPop", width: "400", height: "250" }, {});
};

/**
 * @method
 * @name deleteExcelReq
 * @description delete Excel Req 처리
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} formUpclssNm formUpclssNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteExcelReq = async function (formUpclssCd, formUpclssNm) {
    const _confirm = await $c.win.confirm("서식대분류 '" + formUpclssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ExcelReq').set('formUpclssCd', formUpclssCd);
    scwin.form_listForm.action = "/filing/formUpclass.do";
    $c.util.getComponent('dma_ExcelReq').set('method', "deleteFormUpclass");
    await scwin.tx_fn_Delete_xhr();
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    $c.util.getComponent('dma_ExcelReq').set('method', "downloadFormUpclassList");
    await scwin.tx_fn_Excel();
};
